/*
 * Deterministic mixed-script bidi fuzz (2.0 wave 7).
 * Copyright 2026 The Pt Authors.
 * Licensed under the Apache License, Version 2.0.
 *
 * Reproducible random inputs, fixed seed unless PT_BIDI_FUZZ_SEED overrides it.
 * One generated byte string per iteration is pushed through the three layers
 * that carry bidi state:
 *
 *   1. paragraph analysis and visual runs (offset coverage and levels),
 *   2. the text visual map (logical clusters, finite geometry, boundaries),
 *   3. the entry editing path (visual caret, round trips, selection spans).
 *
 * The assertions are invariants, not golden values: random text has no fixed
 * expected pixels. Iterations come from PT_BIDI_FUZZ_ITERATIONS (default 100,
 * bounded for `make check`); tools/bidi-fuzz.sh raises it for long and
 * sanitizer runs.
 */

#include "../src/internal.h"
#include "harness.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <xkbcommon/xkbcommon-keysyms.h>

#define fuzz_default_iterations 100u
#define fuzz_max_length 256u
#define fuzz_max_codepoints 160u
#define fuzz_caret_steps 2
#define fuzz_buffer_size (fuzz_max_length + 4u)

static uint64_t fuzz_state;

static uint64_t fuzz_next(void) {
    /* xorshift64*: tiny, deterministic and independent of the C library. */
    fuzz_state ^= fuzz_state >> 12;
    fuzz_state ^= fuzz_state << 25;
    fuzz_state ^= fuzz_state >> 27;
    return fuzz_state * 2685821657736338717ull;
}

static unsigned fuzz_below(unsigned bound) {
    return bound ? (unsigned)(fuzz_next() % bound) : 0u;
}

/* Weighted codepoint pool. Latin and neutral ASCII dominate, but every class
 * the adapter has to handle appears often enough to reach the interesting
 * states in a few hundred sequences. */
static const uint32_t fuzz_pool[] = {
    /* Latin, digits, space and punctuation (bidi L, EN/AN, WS, ON). */
    'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'A', 'B', 'Z',
    '0', '1', '2', '3', '4', '7', '9',
    ' ', ' ', ' ', '.', ',', ':', ';', '!', '?', '(', ')', '[', ']',
    '-', '+', '/', '\\', '\'', '"', '#', '%', '&', '@', '*', '=', '_',
    /* Hebrew and Arabic letters. */
    0x05D0u, 0x05D1u, 0x05D2u, 0x05D3u, 0x05D4u, 0x05D5u, 0x05EAu,
    0x0627u, 0x0628u, 0x062Au, 0x0633u, 0x0644u, 0x0645u, 0x0646u, 0x064Au,
    /* Arabic-Indic and extended Arabic-Indic digits (AN). */
    0x0660u, 0x0661u, 0x0669u, 0x06F0u, 0x06F1u, 0x06F9u,
    /* CJK (L) and full-width punctuation (ON). */
    0x4E00u, 0x4E01u, 0x4E02u, 0x4E10u, 0x4E20u, 0x3042u, 0xAC00u,
    0x3001u, 0x3002u, 0xFF01u, 0xFF08u, 0xFF09u,
    /* Combining marks (NSM) that must never split a caret stop. */
    0x0301u, 0x0308u, 0x05B0u, 0x05B4u, 0x064Eu, 0x0651u,
    /* Bidi formatting controls, including every X9 removed class. */
    0x202Au, 0x202Bu, 0x202Cu, 0x202Du, 0x202Eu,
    0x2066u, 0x2067u, 0x2068u, 0x2069u,
    0x200Eu, 0x200Fu, 0x061Cu,
    0x200Bu, 0x200Cu, 0x200Du,
    /* Emoji: supplementary plane, ZWJ sequences and modifiers. */
    0x1F600u, 0x1F601u, 0x1F1E6u, 0x1F1E7u, 0x1F3FBu, 0x2764u,
};
#define fuzz_pool_count (sizeof(fuzz_pool) / sizeof(fuzz_pool[0]))

static size_t encode_utf8(uint32_t codepoint, char *out) {
    if (codepoint <= 0x7Fu) {
        out[0] = (char)codepoint;
        return 1;
    }
    if (codepoint <= 0x7FFu) {
        out[0] = (char)(0xC0u | (codepoint >> 6));
        out[1] = (char)(0x80u | (codepoint & 0x3Fu));
        return 2;
    }
    if (codepoint <= 0xFFFFu) {
        out[0] = (char)(0xE0u | (codepoint >> 12));
        out[1] = (char)(0x80u | ((codepoint >> 6) & 0x3Fu));
        out[2] = (char)(0x80u | (codepoint & 0x3Fu));
        return 3;
    }
    out[0] = (char)(0xF0u | (codepoint >> 18));
    out[1] = (char)(0x80u | ((codepoint >> 12) & 0x3Fu));
    out[2] = (char)(0x80u | ((codepoint >> 6) & 0x3Fu));
    out[3] = (char)(0x80u | (codepoint & 0x3Fu));
    return 4;
}

/* Builds a valid UTF-8 string whose byte length is `target` when the next
 * codepoint still fits, otherwise the closest smaller length. Iteration 0 is
 * empty and iteration 1 is exactly fuzz_max_length bytes. */
static size_t generate_text(unsigned iteration, char *buffer) {
    size_t target;
    if (iteration == 0u) {
        target = 0u;
    } else if (iteration == 1u) {
        target = fuzz_max_length;
    } else {
        target = fuzz_below(fuzz_max_length + 1u);
    }
    size_t length = 0;
    unsigned emitted = 0;
    while (length < target && emitted < fuzz_max_codepoints) {
        uint32_t codepoint = fuzz_pool[fuzz_below((unsigned)fuzz_pool_count)];
        char encoded[4];
        size_t bytes = encode_utf8(codepoint, encoded);
        if (length + bytes > target && target - length > 0u) {
            if (length + bytes > fuzz_max_length) {
                break;
            }
            /* Pad with ASCII so every reachable length stays represented. */
            encoded[0] = (char)('a' + (char)fuzz_below(26));
            bytes = 1;
        }
        if (length + bytes > fuzz_max_length) {
            break;
        }
        memcpy(buffer + length, encoded, bytes);
        length += bytes;
        ++emitted;
    }
    buffer[length] = '\0';
    return length;
}

typedef struct byte_range {
    size_t offset;
    size_t length;
} byte_range;

static int compare_range(const void *left, const void *right) {
    const byte_range *a = left;
    const byte_range *b = right;
    if (a->offset < b->offset) {
        return -1;
    }
    if (a->offset > b->offset) {
        return 1;
    }
    return 0;
}

static void check_line(pt_bidi_line *line, size_t expected_length) {
    pt_check(line->base_level == 0u || line->base_level == 1u);
    if (expected_length == 0u) {
        pt_check(line->run_count == 0u);
        return;
    }
    pt_check(line->run_count > 0u);
    byte_range *ranges = calloc(line->run_count, sizeof(*ranges));
    pt_check(ranges != NULL);
    if (!ranges) {
        return;
    }
    for (size_t i = 0; i < line->run_count; ++i) {
        const pt_bidi_run *run = &line->runs[i];
        pt_check(run->length > 0u);
        pt_check(run->offset <= expected_length);
        pt_check(run->length <= expected_length - run->offset);
        pt_check(run->level <= 126u);
        pt_check(run->visual_index < line->run_count);
        ranges[i].offset = run->offset;
        ranges[i].length = run->length;
    }
    /* Runs are visual order, so offsets are a permutation: sorting them must
     * reconstruct one contiguous [0, expected_length) cover with no gaps and
     * no overlaps. */
    qsort(ranges, line->run_count, sizeof(*ranges), compare_range);
    size_t cursor = 0;
    bool contiguous = true;
    for (size_t i = 0; i < line->run_count; ++i) {
        if (ranges[i].offset != cursor) {
            contiguous = false;
        }
        cursor += ranges[i].length;
    }
    pt_check(contiguous);
    pt_check(cursor == expected_length);
    free(ranges);
}

static void check_paragraph_and_line(const char *text, size_t length) {
    pt_bidi_paragraph *paragraph = NULL;
    pt_check(pt_bidi_paragraph_analyze(text, length, pt_bidi_base_auto, &paragraph));
    pt_check(paragraph != NULL);
    if (!paragraph) {
        return;
    }
    uint8_t base = pt_bidi_paragraph_base_level(paragraph);
    pt_check(base == 0u || base == 1u);
    pt_check(pt_bidi_paragraph_length(paragraph) == length);
    pt_bidi_line line = {0};
    pt_check(pt_bidi_line_create(paragraph, 0, length, &line));
    check_line(&line, length);
    pt_bidi_line_free(&line);

    /* Explicit bases must resolve deterministically and preserve coverage. */
    pt_bidi_base bases[2] = {pt_bidi_base_ltr, pt_bidi_base_rtl};
    for (size_t i = 0; i < 2; ++i) {
        pt_bidi_paragraph *explicit_paragraph = NULL;
        pt_check(pt_bidi_paragraph_analyze(text, length, bases[i], &explicit_paragraph));
        if (!explicit_paragraph) {
            continue;
        }
        pt_check(pt_bidi_paragraph_base_level(explicit_paragraph) ==
                 (bases[i] == pt_bidi_base_rtl ? 1u : 0u));
        pt_bidi_line explicit_line = {0};
        pt_check(pt_bidi_line_create(explicit_paragraph, 0, length, &explicit_line));
        check_line(&explicit_line, length);
        pt_bidi_line_free(&explicit_line);
        pt_bidi_paragraph_free(explicit_paragraph);
    }
    pt_bidi_paragraph_free(paragraph);
}

static bool map_geometry_valid(const pt_text_visual_map *map) {
    if (!isfinite(map->width) || map->width < 0.0f) {
        return false;
    }
    float previous_end = 0.0f;
    for (size_t i = 0; i < map->count; ++i) {
        const pt_text_visual_cluster *cluster = &map->clusters[i];
        if (!isfinite(cluster->x0) || !isfinite(cluster->x1) ||
            !isfinite(cluster->start_x) || !isfinite(cluster->end_x)) {
            return false;
        }
        if (cluster->x0 < -0.01f || cluster->x1 > map->width + 0.05f) {
            return false;
        }
        if (cluster->x0 > cluster->x1 ||
            cluster->start_x < cluster->x0 - 0.01f ||
            cluster->start_x > cluster->x1 + 0.01f ||
            cluster->end_x < cluster->x0 - 0.01f ||
            cluster->end_x > cluster->x1 + 0.01f) {
            return false;
        }
        if (i > 0) {
            const pt_text_visual_cluster *previous = &map->clusters[i - 1];
            if (cluster->start < previous->start || cluster->end < previous->end) {
                return false;
            }
            if (cluster->start != previous->end) {
                return false;
            }
            previous_end = previous->end;
        }
        if (cluster->level > 126u) {
            return false;
        }
    }
    if (map->count > 0) {
        if (map->clusters[0].start != map->start ||
            map->clusters[map->count - 1].end != map->end) {
            return false;
        }
        (void)previous_end;
    }
    return true;
}

static void check_boundaries(const pt_text_visual_map *map) {
    size_t position = map->start;
    size_t steps = 0;
    while (position < map->end) {
        size_t next = pt_text_visual_map_next_boundary(map, position);
        pt_check(next > position);
        pt_check(next <= map->end);
        pt_check(pt_text_visual_map_is_boundary(map, next));
        position = next;
        if (++steps > map->end - map->start + 1u) {
            pt_check(false);
            break;
        }
    }
    pt_check(position == map->end);
    position = map->end;
    steps = 0;
    while (position > map->start) {
        size_t previous = pt_text_visual_map_prev_boundary(map, position);
        pt_check(previous < position);
        pt_check(previous >= map->start);
        pt_check(pt_text_visual_map_is_boundary(map, previous));
        position = previous;
        if (++steps > map->end - map->start + 1u) {
            pt_check(false);
            break;
        }
    }
    pt_check(position == map->start);
    for (size_t i = 0; i < map->count; ++i) {
        pt_check(pt_text_visual_map_is_boundary(map, map->clusters[i].start));
    }
    pt_check(pt_text_visual_map_is_boundary(map, map->end));
}

static void check_visual_map(const pt_text_visual_map *map, pt_font *font,
                             const char *text, size_t length, pt_bidi_base base) {
    pt_check(map != NULL);
    if (!map) {
        return;
    }
    pt_check(map->base_level == 0u || map->base_level == 1u);
    pt_check(map->start <= map->end && map->end <= length);
    pt_check(map_geometry_valid(map));
    pt_check_near(pt_text_visual_map_width(map),
                  pt_font_measure_bidi(font, text, length, base), 0.5f);
    check_boundaries(map);

    if (map->count > 0) {
        pt_text_visual_cluster *first = &map->clusters[0];
        pt_text_visual_cluster *last = &map->clusters[map->count - 1];
        pt_check(first->start == map->start);
        pt_check(last->end == map->end);
        for (size_t i = 1; i < map->count; ++i) {
            pt_check(map->clusters[i - 1].start <= map->clusters[i].start);
        }
    }
    if (length == 0u) {
        pt_check(map->count == 0u);
        pt_check(pt_text_visual_map_width(map) == 0.0f);
    }

    /* Every cluster boundary maps to an x inside the line. The map's position
     * lookup must accept both edge and interior x without reading past. */
    for (size_t i = 0; i < map->count; ++i) {
        size_t position = map->clusters[i].start;
        float x = pt_text_visual_map_x_for_position(map, position, pt_text_bias_leading);
        pt_check(isfinite(x));
        pt_check(x >= -0.01f && x <= map->width + 0.05f);
        size_t hit = pt_text_visual_map_position_for_x(map, x, pt_text_bias_leading);
        pt_check(hit >= map->start && hit <= map->end);
        pt_check(isfinite(pt_text_visual_map_x_for_position(
            map, hit, pt_text_bias_leading)));
    }
}

/* Entry caret x in the entry's local line coordinates, mirroring the helper in
 * test_editing: IME rectangles are window-relative and RTL lines are anchored
 * to the right. */
static float entry_caret_visual_x(pt_widget *entry) {
    int x = 0;
    pt_widget_ime_rect(entry, &x, NULL, NULL, NULL);
    const char *text = entry->text ? entry->text : "";
    size_t length = strlen(text);
    pt_layout_ctx ctx = pt_layout_context_for(entry);
    pt_font *font = pt_widget_font_for(entry, &ctx);
    float scale = ctx.scale > 0.0f ? ctx.scale : 1.0f;
    float origin = -entry->scroll_x;
    pt_bidi_base base = pt_widget_text_base(entry, text, length);
    if (font && base == pt_bidi_base_rtl) {
        float area_w = pt_max_float(0.0f, entry->width - entry->padding_left -
                                              entry->padding_right);
        origin = area_w - pt_font_measure_bidi(font, text, length, base) / scale +
                 entry->scroll_x;
    }
    return (float)x - entry->x - entry->padding_left - origin;
}

static float entry_map_caret_x(const pt_text_visual_map *map, pt_widget *entry,
                               float scale) {
    if (!map || scale <= 0.0f) {
        return 0.0f;
    }
    return pt_text_visual_map_x_for_position(map, entry->cursor,
                                             (pt_text_bias)entry->caret_affinity) /
           scale;
}

/* Reproduces the painter's span collection and x merge: selection rectangles
 * must be finite, inside the line and sorted left to right without overlap.
 * The map is built once per iteration and shared with the caret checks. */
static void check_selection_spans(const pt_text_visual_map *map, uint32_t from, uint32_t to,
                                  size_t length) {
    if (!map) {
        return;
    }
    float *spans = calloc(map->count * 2u + 1u, sizeof(*spans));
    pt_check(spans != NULL);
    if (!spans) {
        return;
    }
    size_t span_count = 0;
    for (size_t i = 0; i < map->count; ++i) {
        const pt_text_visual_cluster *cluster = &map->clusters[i];
        if (cluster->end <= from || cluster->start >= to || cluster->x1 <= cluster->x0) {
            continue;
        }
        spans[span_count * 2u] = cluster->x0;
        spans[span_count * 2u + 1u] = cluster->x1;
        ++span_count;
    }
    /* Insertion sort by x0; span_count is small, and this avoids a struct. */
    for (size_t i = 1; i < span_count; ++i) {
        float x0 = spans[i * 2u];
        float x1 = spans[i * 2u + 1u];
        size_t j = i;
        while (j > 0 && spans[(j - 1u) * 2u] > x0) {
            spans[j * 2u] = spans[(j - 1u) * 2u];
            spans[j * 2u + 1u] = spans[(j - 1u) * 2u + 1u];
            --j;
        }
        spans[j * 2u] = x0;
        spans[j * 2u + 1u] = x1;
    }
    float previous = -1.0f;
    for (size_t i = 0; i < span_count; ++i) {
        float x0 = spans[i * 2u];
        float x1 = spans[i * 2u + 1u];
        pt_check(isfinite(x0) && isfinite(x1));
        pt_check(x0 >= -0.01f && x1 <= map->width + 0.05f);
        pt_check(x1 > x0);
        pt_check(x0 >= previous - 0.01f);
        previous = x1;
    }
    if (from == 0u && to >= length && map->width > 0.5f) {
        /* A full selection covers the whole line, including any zero-width
         * controls that add no span. */
        pt_check(span_count > 0u);
        if (span_count > 0u) {
            pt_check_near(spans[0], 0.0f, 0.05f);
            pt_check_near(spans[(span_count - 1u) * 2u + 1u], map->width, 0.05f);
        }
    }
    free(spans);
}

static void check_editing(pt_window *window, pt_widget *entry, pt_canvas *canvas,
                          const pt_text_visual_map *map, const char *text, size_t length,
                          unsigned iteration) {
    if (strcmp(pt_widget_get_text(entry), text) != 0) {
        pt_check(false);
        return;
    }
    pt_layout_ctx ctx = pt_layout_context_for(entry);
    float scale = ctx.scale > 0.0f ? ctx.scale : 1.0f;
    /* The IME/caret x comparison is exact only while the whole line fits the
     * entry; overflowing text scrolls, and the scroll offset is a separate
     * contract covered by test_editing. */
    float content_width = pt_max_float(0.0f, entry->width - entry->padding_left -
                                             entry->padding_right);
    bool fits = map && (map->width / (scale > 0.0f ? scale : 1.0f)) <= content_width + 0.5f;
    pt_entry_set_selection(entry, 0, 0);
    float previous_x = entry_caret_visual_x(entry);
    pt_check(isfinite(previous_x));

    for (int step = 0; step < fuzz_caret_steps; ++step) {
        pt_window_input_key(window, XKB_KEY_Right, 0, NULL, true);
        pt_check(entry->cursor <= length);
        float x = entry_caret_visual_x(entry);
        pt_check(isfinite(x));
        /* Visual Right never moves the caret left. */
        pt_check(x >= previous_x - 0.51f);
        /* A caret on a grapheme cluster that the entry's shaping splits at a
         * different byte offset than the plain map has no single expected x;
         * the map contract covers cluster boundaries only. */
        if (fits && pt_text_visual_map_is_boundary(map, entry->cursor)) {
            pt_check_near(x, entry_map_caret_x(map, entry, scale), 1.0f);
        }
        previous_x = x;
    }
    float right_x = previous_x;
    for (int step = 0; step < fuzz_caret_steps; ++step) {
        pt_window_input_key(window, XKB_KEY_Left, 0, NULL, true);
        pt_check(entry->cursor <= length);
        float x = entry_caret_visual_x(entry);
        pt_check(isfinite(x));
        pt_check(x <= previous_x + 0.51f);
        /* A caret on a grapheme cluster that the entry's shaping splits at a
         * different byte offset than the plain map has no single expected x;
         * the map contract covers cluster boundaries only. */
        if (fits && pt_text_visual_map_is_boundary(map, entry->cursor)) {
            pt_check_near(x, entry_map_caret_x(map, entry, scale), 1.0f);
        }
        previous_x = x;
    }
    /* The two directions do not oscillate across each other. */
    pt_check(previous_x <= right_x + 1.0f);

    if ((iteration & 3u) == 0u) {
        pt_window_input_key(window, XKB_KEY_Home, 0, NULL, true);
        float home_x = entry_caret_visual_x(entry);
        pt_window_input_key(window, XKB_KEY_End, 0, NULL, true);
        float end_x = entry_caret_visual_x(entry);
        pt_check(isfinite(home_x) && isfinite(end_x));
        /* Home is the visual left edge in both paragraph directions; End is
         * the visual right edge, so the order never inverts. */
        pt_check(home_x <= end_x + 1.0f);

        /* Shift+Right keeps the anchor and grows a logical selection. */
        pt_entry_set_selection(entry, 0, 0);
        pt_window_input_key(window, XKB_KEY_Right, 1u, NULL, true);
        pt_check(entry->selection_anchor == 0u);
        pt_check(entry->cursor <= length);
    }

    uint32_t from = length ? (uint32_t)fuzz_below((unsigned)length + 1u) : 0u;
    uint32_t to = length ? (uint32_t)fuzz_below((unsigned)length + 1u) : 0u;
    if (from > to) {
        uint32_t swap = from;
        from = to;
        to = swap;
    }
    pt_entry_set_selection(entry, from, to);
    uint32_t seen_from = 0;
    uint32_t seen_to = 0;
    bool selected = pt_entry_get_selection(entry, &seen_from, &seen_to);
    if (from == to) {
        pt_check(!selected || (seen_from == from && seen_to == to));
    } else {
        pt_check(selected && seen_from == from && seen_to == to);
    }
    check_selection_spans(map, from, to, length);
    if ((iteration & 15u) == 0u) {
        check_selection_spans(map, 0, (uint32_t)length, length);
    }

    /* Exercise the paint path for a slice of the corpus; the rest checks the
     * geometry directly, which keeps the loop inside its time budget. */
    if ((iteration & 15u) == 0u) {
        int x = 0;
        int y = 0;
        int w = 0;
        int h = 0;
        pt_widget_ime_rect(entry, &x, &y, &w, &h);
        pt_check(isfinite((float)x) && isfinite((float)y));
        pt_unused(w);
        pt_unused(h);
        window->needs_draw = true;
        pt_check(pt_window_paint(window, canvas));
    }
}

int main(void) {
    unsigned iterations = fuzz_default_iterations;
    const char *iterations_env = getenv("PT_BIDI_FUZZ_ITERATIONS");
    if (iterations_env && iterations_env[0]) {
        char *end = NULL;
        unsigned long parsed = strtoul(iterations_env, &end, 10);
        if (end && *end == '\0' && parsed > 0ul && parsed <= 1000000ul) {
            iterations = (unsigned)parsed;
        }
    }
    uint64_t seed_initial = 0x9E3779B97F4A7C15ull;
    fuzz_state = seed_initial;
    const char *seed_env = getenv("PT_BIDI_FUZZ_SEED");
    if (seed_env && seed_env[0]) {
        char *end = NULL;
        unsigned long long parsed = strtoull(seed_env, &end, 0);
        if (end && *end == '\0' && parsed != 0ull) {
            fuzz_state = (uint64_t)parsed;
            seed_initial = fuzz_state;
        }
    }

    setenv("PT_HEADLESS", "1", 1);
    pt_app *app = pt_app_create("pt.tests.bidi-fuzz");
    pt_check(app != NULL);
    pt_window *window = NULL;
    pt_widget *entry = NULL;
    pt_canvas *canvas = NULL;
    if (app) {
        pt_app_set_font_family(app, "DejaVu Sans");
        window = pt_window_create(app, "bidi fuzz", 640, 200);
        pt_check(window != NULL);
        if (window) {
            pt_widget *root = pt_window_root(window);
            pt_widget_set_padding(root, 10.0f, 10.0f, 10.0f, 10.0f);
            entry = pt_entry_create(root, "");
            pt_check(entry != NULL);
            if (entry) {
                pt_widget_set_size(entry, 600.0f, 32.0f);
                pt_widget_set_font_size(entry, 18.0f);
                pt_widget_set_align_self(entry, pt_align_start);
            }
            pt_window_show(window);
            pt_check(pt_widget_focus(entry));
            window->caret_visible = true;
            canvas = pt_canvas_create(640, 200, 1.0f);
            pt_check(canvas != NULL);
        }
    }

    pt_layout_ctx fuzz_ctx = pt_layout_context_for(entry);
    pt_font *font = entry ? pt_widget_font_for(entry, &fuzz_ctx) : NULL;
    bool have_font = font && pt_font_has_glyph(font, 0x05D0u) &&
                     pt_font_has_glyph(font, 0x0627u) && entry && window && canvas;
    if (!have_font) {
        printf("skip bidi fuzz: DejaVu Sans with Arabic and Hebrew is unavailable\n");
    }

    char buffer[fuzz_buffer_size];
    for (unsigned iteration = 0; iteration < iterations; ++iteration) {
        size_t length = generate_text(iteration, buffer);
        check_paragraph_and_line(buffer, length);
        if (!have_font) {
            continue;
        }
        pt_bidi_base bases[3] = {pt_bidi_base_auto, pt_bidi_base_ltr, pt_bidi_base_rtl};
        pt_bidi_base base = bases[iteration % 3u];
        pt_text_direction directions[3] = {pt_text_direction_auto, pt_text_direction_ltr,
                                           pt_text_direction_rtl};
        pt_widget_set_text_direction(entry, directions[iteration % 3u]);
        pt_widget_set_text(entry, buffer);
        /* A new text resets the horizontal scroll to its anchor; the fuzz
         * case owns the widget, so clear the previous value explicitly. */
        entry->scroll_x = 0.0f;
        pt_text_visual_map *map = NULL;
        pt_check(pt_text_visual_map_build_bidi(font, buffer, length, base, &map));
        check_visual_map(map, font, buffer, length, base);
        check_editing(window, entry, canvas, map, buffer, length, iteration);
        pt_text_visual_map_free(map);
    }

    pt_canvas_destroy(canvas);
    if (app) {
        pt_app_destroy(app);
    }
    pt_font_manager_shutdown();
    printf("bidi fuzz: %u determined sequence(s), seed 0x%016llx (final state 0x%016llx)\n",
           iterations, (unsigned long long)seed_initial,
           (unsigned long long)fuzz_state);
    return pt_test_finish("bidi_fuzz");
}